// node p.mjs <label> [k=v ...]  (env PRAGMA optional)
import http from "node:http"; import { spawn } from "node:child_process"; import fs from "node:fs"; import os from "node:os"; import { join } from "node:path";
const [label, ...extra] = process.argv.slice(2), N = 1550, TOKEN = "t" + process.pid;
const payload = Array.from({ length: N }, (_, i) => `L${String(i + 1).padStart(5, "0")} ${"prd-text ".repeat(8)}`.padEnd(79, ".") + "\n").join("");
const read = (q) => new Promise((ok) => { let s = ""; q.on("data", (c) => { s += c; }); q.on("end", () => ok(s)); });
const mcp = http.createServer(async (q, r) => {
  if (q.method !== "POST") return r.writeHead(405).end();
  if (q.headers.authorization !== `Bearer ${TOKEN}`) return r.writeHead(401).end();
  const m = JSON.parse(await read(q));
  if (m.id === undefined) return r.writeHead(202).end();
  const result = m.method === "initialize" ? { protocolVersion: m.params.protocolVersion, capabilities: { tools: {} }, serverInfo: { name: "p", version: "1" } }
    : m.method === "tools/list" ? { tools: [{ name: "read_big", inputSchema: { type: "object", properties: {} } }] }
    : { content: [{ type: "text", text: payload }] };
  r.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify({ jsonrpc: "2.0", id: m.id, result }));
});
const sse = (r, item) => {
  r.writeHead(200, { "content-type": "text/event-stream" });
  for (const d of [{ type: "response.created", response: { id: "x" } }, { type: "response.output_item.done", output_index: 0, item },
    { type: "response.completed", response: { id: "x", usage: { input_tokens: 1, output_tokens: 1, total_tokens: 2 } } }]) r.write(`data: ${JSON.stringify(d)}\n\n`);
  r.end();
};
const say = (text) => ({ type: "message", role: "assistant", content: [{ type: "output_text", text }] });
const model = http.createServer(async (q, r) => {
  const b = JSON.parse(await read(q));
  if (b.model === "codex-auto-review") return sse(r, say('{"outcome":"allow"}')); // the auto_review guardian
  const out = b.input.find((i) => /call_output$/u.test(i.type) && i.call_id === "c1");
  if (out) {
    const t = JSON.stringify(out.output), got = new Set(t.match(/L\d{5}/gu));
    console.log(JSON.stringify({ label, model: b.model, chars: t.length, lines: `${got.size}/${N}`, markers: t.match(/…\d+ tokens truncated…|original token count: \d+/gu) }));
    return sse(r, say("DONE"));
  }
  if (b.tools?.some((t) => t.type === "tool_search")) { // direct-tool model
    const found = b.input.find((i) => i.type === "tool_search_output");
    if (!found) return sse(r, { type: "tool_search_call", call_id: "s1", execution: "client", arguments: { query: "read_big" } });
    const ns = found.tools.find((t) => JSON.stringify(t).includes("read_big")), fn = ns.tools?.find((t) => t.name.includes("read_big")) ?? ns;
    return sse(r, { type: "function_call", call_id: "c1", name: fn.name, ...(ns === fn ? {} : { namespace: ns.name }), arguments: "{}" });
  }
  const pragma = process.env.PRAGMA ? `// @exec: ${process.env.PRAGMA}\n` : ""; // code-mode model
  sse(r, { type: "custom_tool_call", call_id: "c1", name: "exec", input: `${pragma}const v = await tools[ALL_TOOLS.find((t) => t.name.includes("read_big")).name]({});\ntext(v.content.map((c) => c.text).join(""));\n` });
});
const port = (s) => new Promise((ok) => s.listen(0, "127.0.0.1", () => ok(s.address().port)));
const [mp, pp] = [await port(mcp), await port(model)], home = fs.mkdtempSync(join(os.tmpdir(), "p-"));
fs.copyFileSync(join(os.homedir(), ".codex", "models_cache.json"), join(home, "models_cache.json")); // the host catalog
const argv = ["exec", "--ignore-user-config", "--skip-git-repo-check", "--ephemeral", "--sandbox", "read-only", // chain seat, agent-spawner.ts
  "-c", "approval_policy=on-request", "-c", "approvals_reviewer=auto_review", "-c", `mcp_servers.moe-next.url=http://127.0.0.1:${mp}`,
  "-c", "mcp_servers.moe-next.bearer_token_env_var=MOE_AGENT_MCP_BEARER", "-c", "mcp_servers.moe-next.disabled_tools=[]",
  ...extra.flatMap((kv) => ["-c", kv]), "-c", "model_provider=p", "-c", "model_providers.p.name=p",
  "-c", `model_providers.p.base_url=http://127.0.0.1:${pp}/v1`, "-c", "model_providers.p.wire_api=responses", "-"];
const child = spawn("codex", argv, { env: { ...process.env, CODEX_HOME: home, MOE_AGENT_MCP_BEARER: TOKEN }, stdio: ["pipe", "ignore", "ignore"] });
child.stdin.end("Call read_big once, then reply DONE.\n");
child.on("exit", (code) => { console.log("codex exit", code); process.exit(); });
